"""v0.214: Growth's Brain, incremento 2 — leads e vendas no registro central de metas (espelho com o planejamento do mês), metas das
campanhas (janela da captação e do carrinho), metas por produto (criadas no Planejamento anual), cobertura parcial e o Cockpit com tudo.
Banco fa (Escola Aurora), com 20261207100000_brain_metas.sql e 20261208100000_brain_metas_2.sql. Cria os dados de teste e apaga no fim."""
import sys, os, json, subprocess; sys.path.insert(0, '.')
import front
from playwright.sync_api import sync_playwright
WS = 'ac56e719-7325-4062-aa47-74bc2141f89d'
SHOT = '/tmp/claude-0/-home-claude/6d4aa2ee-cf0f-5c9b-bd48-3047ac34b6ff/scratchpad/shots214/'; os.makedirs(SHOT, exist_ok=True)
def sql(q):
    r = subprocess.run(['psql', '-h', '/var/run/postgresql', '-p', '55432', '-U', 'postgres', '-d', 'fa', '-Atq', '-v', 'ON_ERROR_STOP=1', '-c', q], capture_output=True, text=True)
    if r.returncode: raise Exception(r.stderr.strip())
    return r.stdout.strip()
falhas = []
def chk(c, msg, extra=''):
    print(('ok   ' if c else 'FALHA ') + msg + ((' → ' + str(extra)[:300]) if not c and extra != '' else ''))
    if not c: falhas.append(msg)
brl = lambda v: ('−' if v < 0 else '') + 'R$ ' + f'{abs(v):,.2f}'.replace(',', 'X').replace('.', ',').replace('X', '.')
nb = lambda t: t.replace('\xa0', ' ')
CAMP = sql(f"select id from campanhas where workspace_id = '{WS}' and nome = 'Lançamento Setembro'")
CB = sql(f"select meta_leads || '|' || meta_vendas || '|' || meta_receita || '|' || coalesce(fases::text, 'null') || '|' || coalesce(data_carrinho_abre::text, '') || '|' || coalesce(data_carrinho_fecha::text, '') from campanhas where id = '{CAMP}'")
PROD = sql(f"select id from produtos where workspace_id = '{WS}' and nome = 'Curso Base'")
def limpa():
    sql(f"update campanhas set meta_leads = 700, meta_vendas = 45, meta_receita = 44865, meta_leads_mes = null, data_carrinho_abre = null, data_carrinho_fecha = null where id = '{CAMP}'")
    sql(f"delete from metas_fotos where workspace_id = '{WS}'"); sql(f"delete from planejamento_mensal where workspace_id = '{WS}'"); sql(f"delete from plano_anual where workspace_id = '{WS}'")
    sql(f"delete from metas where workspace_id = '{WS}' and escopo <> 'campanha'")
    sql(f"select metas_de_campanha_grava(c) from campanhas c where c.id = '{CAMP}'")
limpa()
A = lambda met, ini, fim, h, esc='empresa', ref=None: json.loads(sql(f"select metas_avaliar_interno('{WS}', '{met}', '{ini}', '{fim}', '{h}', '{esc}', {('%r' % ref) if ref else 'null'})"))
# ---------------- leads e vendas da empresa ----------------
sql(f"insert into planejamento_mensal (workspace_id, ano, mes, meta_leads, meta_vendas, orcamento) values ('{WS}', 2026, 10, 500, 20, 3000)")
chk(sql(f"select string_agg(metrica || ':' || valor::int, ',' order by metrica) from metas where workspace_id = '{WS}' and escopo = 'empresa' and status = 'aprovada'") == 'leads:500,vendas:20', 'metas de leads e vendas do mês entram no registro central (orçamento não)')
sql(f"update metas set valor = 550 where workspace_id = '{WS}' and metrica = 'leads' and escopo = 'empresa' and status = 'aprovada'")
chk(sql(f"select meta_leads || ':' || meta_vendas || ':' || orcamento::int from planejamento_mensal where workspace_id = '{WS}' and mes = 10") == '550:20:3000', 'mudar a meta de leads no registro muda só a coluna de leads do mês')
leads_out = int(sql(f"select count(*) from pessoas where workspace_id = '{WS}' and coalesce(captada, true) and (criado_em at time zone 'America/Sao_Paulo')::date between '2026-10-01' and '2026-10-31'"))
vp = json.loads(sql(f"select set_config('request.jwt.claims', '{{\"sub\":\"00000000-0000-0000-0000-00000000a0a0\"}}', true), vendas_periodo('{WS}', '2026-10-01', '2026-10-31')").split('|', 1)[1])
L = A('leads', '2026-10-01', '2026-10-31', '2026-11-01')
chk(int(L['realizado']) == leads_out == int(vp['leads']) and L['meta'] == 550, 'leads de outubro: o mesmo número do Dashboard de vendas (vendas_periodo)', (L['realizado'], leads_out, vp['leads']))
V = A('vendas', '2026-10-01', '2026-10-31', '2026-11-01')
chk(int(V['realizado']) == int(vp['vendas']) and V['unidade'] == 'num', 'vendas de outubro: o mesmo número do Dashboard de vendas', (V['realizado'], vp['vendas']))
P2 = A('leads', '2026-10-01', '2026-11-30', '2026-11-20')
chk(P2['parcial'] is True and int(P2['realizado']) == leads_out and P2['meta'] == 550, 'período com parte sem meta: "cobertura parcial" e o realizado só nos dias com meta', P2)
# ---------------- campanhas ----------------
rows = sql(f"select string_agg(metrica || ':' || valor::numeric(12,0) || ':' || ini || ':' || fim, ',' order by metrica) from metas where campanha_id = '{CAMP}' and status = 'aprovada'")
chk(rows == 'faturamento:44865:2026-09-01:2026-09-30,leads:700:2026-09-01:2026-09-30,vendas:45:2026-09-01:2026-09-30', 'metas da campanha no registro (leads, vendas, faturamento), na janela da campanha', rows)
V0 = int(sql(f"select versao from metas where campanha_id = '{CAMP}' and status = 'aprovada' and metrica = 'vendas'"))
sql(f"update campanhas set data_carrinho_abre = '2026-09-21', data_carrinho_fecha = '2026-09-27', meta_vendas = 40 where id = '{CAMP}'")
r = sql(f"select string_agg(metrica || ':' || valor::int || ':' || ini || ':' || fim || ':' || versao, ',' order by metrica) from metas where campanha_id = '{CAMP}' and status = 'aprovada' and metrica <> 'leads'")
chk(r == f'faturamento:44865:2026-09-21:2026-09-27:{V0 + 1},vendas:40:2026-09-21:2026-09-27:{V0 + 1}', 'mudar a campanha (carrinho e meta) atualiza a meta: vendas e faturamento na janela do carrinho, com versão nova', r)
mid = A('vendas', '2026-09-21', '2026-09-27', '2026-09-24', 'campanha', CAMP)
v24 = int(sql(f"select count(*) from vendas where campanha_id = '{CAMP}' and status = 'aprovada' and (data_venda at time zone 'America/Sao_Paulo')::date between '2026-09-21' and '2026-09-24'"))
chk(abs(mid['esperado'] - 40 * 4 / 7) < 0.02 and int(mid['realizado']) == v24, 'campanha no meio do carrinho: esperado = 4 de 7 dias da meta, realizado = vendas da campanha até o dia', (mid['esperado'], mid['realizado'], v24))
sql(f"update campanhas set meta_leads_mes = 100 where id = '{CAMP}'")
chk(sql(f"select count(*) from metas where campanha_id = '{CAMP}' and metrica = 'leads' and status = 'aprovada'") == '0', 'campanha perpétua com meta por mês: a meta de leads sai do registro (fica para o próximo incremento)')
sql(f"update campanhas set meta_leads_mes = null where id = '{CAMP}'")
rc = json.loads(sql(f"select set_config('growths.metas_interno', '1', true), metas_recortes('{WS}', '2026-09-01', '2026-09-30', '2026-11-01')").split('|', 1)[1])
chk(len(rc) == 3 and all(x['nome'] == 'Lançamento Setembro' for x in rc) and [x['metrica'] for x in rc] == ['leads', 'vendas', 'faturamento'], 'recortes do período: as 3 metas da campanha, com o nome', [(x['nome'], x['metrica']) for x in rc])
sql("select metas_fotografar('2026-09-24')")
chk(sql(f"select count(*) from metas_fotos where workspace_id = '{WS}' and escopo = 'campanha' and dia = '2026-09-24'") == '3', 'foto diária também das metas de campanha em andamento')
# ---------------- telas ----------------
with sync_playwright() as pw:
    b = pw.chromium.launch()
    ctx, pg = front.abre(b, hoje='2026-11-01', vw=1440, vh=1000)
    front.vai(pg, 'cockpit', "S.perD = { ini: '2026-09-01', fim: '2026-10-31' };", 9000)
    t = nb(pg.inner_text('#main .ck-metas'))
    chk('Leads e vendas da empresa' in t and 'Campanhas e produtos com meta' in t and t.count('Lançamento Setembro') == 3, 'Cockpit: tabela de leads e vendas da empresa e as 3 metas da campanha', t[:500])
    chk('parcial' in t, 'Cockpit: leads com cobertura parcial marcados (setembro sem meta)')
    pg.locator('#main .ck-metas').screenshot(path=SHOT + '1_cockpit_metas.png')
    pg.click('#main [data-mtc] >> nth=0'); pg.wait_for_timeout(6000)
    chk(pg.evaluate('S.view') == 'mkt-camp' and pg.evaluate('S.campSel') == CAMP, 'clicar na meta da campanha abre a campanha')
    front.vai(pg, 'mkt-camp', "S.tabMkt = 'plan'; S.campSel = null; S.ano = 2026;", 9000)
    t = nb(pg.inner_text('#paObj'))
    chk('Metas por produto e por campanha' in t and t.count('Lançamento Setembro') == 3 and 'Leads: 1 mês(es) com meta' in t, 'Planejamento anual: metas da campanha listadas e contagem dos meses de leads', t[:500])
    pg.click('#paMetaProd'); pg.wait_for_timeout(500)
    pg.select_option('#modalRoot [name=produto_id]', PROD); pg.select_option('#modalRoot [name=metrica]', 'faturamento')
    pg.fill('#modalRoot [name=ini]', '2026-10-01'); pg.fill('#modalRoot [name=fim]', '2026-10-31'); pg.fill('#modalRoot [name=valor]', '15000')
    pg.fill('#modalRoot [name=premissa]', 'Metade do faturamento de outubro no Curso Base'); pg.click('#modalRoot .pri'); pg.wait_for_timeout(7000)
    chk(sql(f"select granularidade || ':' || valor::int || ':' || unidade from metas where produto_id = '{PROD}' and status = 'aprovada'") == 'mes:15000:brl' and 'Curso Base' in pg.inner_text('#paObj'), 'criar meta de produto (outubro inteiro vira granularidade "mês")')
    pg.locator('#paObj').screenshot(path=SHOT + '2_planejamento_metas.png')
    fat_cb = float(sql(f"select coalesce(sum(valor_bruto), 0) from vendas where produto_id = '{PROD}' and status = 'aprovada' and (data_venda at time zone 'America/Sao_Paulo')::date between '2026-10-01' and '2026-10-31'"))
    front.vai(pg, 'cockpit', "S.perD = { ini: '2026-10-01', fim: '2026-10-31' };", 9000)
    t = nb(pg.inner_text('#main .ck-metas'))
    chk('Curso Base' in t and brl(fat_cb) in t and brl(15000) in t, 'Cockpit (outubro): meta do Curso Base com o faturamento do produto', t[:600])
    front.vai(pg, 'mkt-camp', "S.tabMkt = 'plan'; S.campSel = null; S.ano = 2026;", 9000)
    pg.click('#paObj [data-pamed]'); pg.wait_for_timeout(500); pg.fill('#modalRoot [name=valor]', '16000'); pg.click('#modalRoot .pri'); pg.wait_for_timeout(6000)
    chk(sql(f"select valor::int || ':' || versao from metas where produto_id = '{PROD}' and status = 'aprovada'") == '16000:2', 'editar a meta de produto cria versão nova')
    pg.click('#paObj [data-pamarq]'); pg.wait_for_timeout(5000)
    chk(sql(f"select status from metas where produto_id = '{PROD}'") == 'arquivada', 'tirar a meta de produto: arquivada (fica no histórico)')
    pg.click('#paObj [data-pamc] >> nth=0'); pg.wait_for_timeout(5000)
    chk(pg.evaluate('S.campSel') == CAMP, 'Planejamento anual: "Abrir a campanha" leva à campanha (a meta da campanha é editada lá)')
    chk(not pg.errs, 'sem erro de JavaScript ' + str(pg.errs[:3]))
    b.close()
limpa()
print('\n%d falha(s)' % len(falhas)); sys.exit(1 if falhas else 0)
